begin; do $$ declare f public.day_d_rtd_folios; r jsonb; mirrored jsonb; begin select * into strict f from public.day_d_rtd_folios where is_demo and municipality_code='0501' and status='BORRADOR' limit 1; update public.day_d_rtd_folios set status='ENVIADO',submitted_at=now(),submission_key='rollback-october-demo' where id=f.id; r:=public.radar_fiscal_publish_rtd_v1(f.id); if not (r->>'published')::boolean then raise exception 'Demo publish failed'; end if; select payload into mirrored from demo_vault.campaign_records where category='RTD_FOLIO' and campaign_id=f.campaign_id and payload->>'source_rtd_folio_id'=f.id::text; if mirrored is null or mirrored->>'rtd_status'<>'ENVIADO' then raise exception 'Demo mirror missing'; end if; end $$; rollback; select 'PASS demo publish and dashboard mirror, rolled back' as result;
